// The free content subset, generated by scripts/build-content.mjs.
import data from "./content.json" with { type: "json" };

export type Category = { id: string; displayName: string; shortName: string; howToSpot: string; requires: string };
export type GlossaryEntry = { id: string; term: string; aliases: string[]; group: string; definition: string };
export type PrimerPage = { id: string; title: string; body: string; tip: string; tiles: string[] };
export type ReferenceSection = { category: string; exampleRack: string[]; watchOut: string };
export type Drill = {
  id: string;
  kind: "flashcards" | "quiz" | "handMatch" | "charleston";
  title: string;
  subtitle: string;
  room: string;
  roomName: string;
  // deno-lint-ignore no-explicit-any
  items: Record<string, any>[];
};

export const content = data as unknown as {
  categories: Category[];
  glossary: GlossaryEntry[];
  primer: PrimerPage[];
  referenceSections: ReferenceSection[];
  drills: Drill[];
};
